mapper.select:
select
*
from t_operate_log


        AND operate_user_id = #{query.operateUserId}


        AND operate_user_type = #{query.operateUserType}


        AND CAST(create_time AS DATE) >= #{query.startDate}


        AND CAST(create_time AS DATE) <= #{query.endDate}


        AND STRPOS(operate_user_name,#{query.userName}) > 0


        AND (STRPOS(module,#{query.keywords}) > 0 OR STRPOS(content,#{query.keywords}) > 0)


        AND (STRPOS(url,#{query.requestKeywords}) > 0 OR STRPOS(method,#{query.requestKeywords}) > 0 OR STRPOS(param,#{query.requestKeywords}) > 0 OR STRPOS(response,#{query.requestKeywords}) > 0)


        AND success_flag = #{query.successFlag}


order by create_time desc
